window.products.push({"id":757553,"name":"Shilucheng Memory Foam Pillows","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/01RmK+J4pJL._AC_.gif","description":"★Neck and Shoulder Pain Hurts★:Loft alone may not relieve your neck pain, if you find yourself trying to pull traditional rectangular pillows around your neck. Our side sleeper pillow was designed to fit around the shoulders and neck, cradle the head and lock in that neutral spine alignment. A side sleeper neck pain pillow allows you to slide your shoulders right into the curve and offers a higher loft under your neck. Giving You More Support When You Sleep.","images":["https://m.media-amazon.com/images/I/01RmK+J4pJL._AC_.gif","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Shilucheng","source_asin":"B01KLCXHGU","category_path":"Home & Kitchen"},"sku":"BM-757553","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B01KLCXHGU","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B01KLCXHGU","price_pending":true,"merchant_ready":false});
